CREATE TABLE IF NOT EXISTS v2_recovery_dispatch(aggregate_type varchar(64) NOT NULL,aggregate_id varchar(128) NOT NULL,observed_state varchar(64) NOT NULL DEFAULT '',observed_version bigint NOT NULL DEFAULT 0,last_event_type varchar(64),last_event_id varchar(128),last_redrive_at datetime(6),next_redrive_at datetime(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),redrive_count int NOT NULL DEFAULT 0,PRIMARY KEY(aggregate_type,aggregate_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
